import sys

def reverse_words(s):
    n = len(s)
    words = []
    i = 0
    while i < n:
        while i < n and s[i] == ' ':
            i += 1
        start = i
        while i < n and s[i] != ' ':
            i += 1
        if start < i:
            words.append(s[start:i])
    return ' '.join(reversed(words))


if __name__ == '__main__':
    s = sys.stdin.read().rstrip('\r\n')
    if not s.strip():
        sys.exit(0)
    print(reverse_words(s))

import sys

def reverse_words(s):
    a = list(s)
    n = len(a)
    a.reverse()
    write = 0
    i = 0
    while i < n:
        if a[i] == ' ':
            i += 1
            continue
        if write > 0:
            a[write] = ' '
            write += 1
        start = write
        while i < n and a[i] != ' ':
            a[write] = a[i]
            write += 1
            i += 1
        a[start:write] = a[start:write][::-1]
    return ''.join(a[:write])


if __name__ == '__main__':
    s = sys.stdin.read().rstrip('\r\n')
    if not s.strip():
        sys.exit(0)
    print(reverse_words(s))
